    await decryptActionBoundArgs("<id>", $$ACTION_CLOSURE_BOUND);
  // after all the closed-over values are available, we can initialize the arguments
  // ({ x = value } = obj, y = x)
  var [{ x = $$ACTION_ARG_0 } = $$ACTION_ARG_1, y = x] = $$ACTION_ARGS;

  return [x, y];
};


```

